def transform(grid):
    """Encode each 3x3 tile by its non-background color, if present."""
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for r in range(h // 3):
        for c in range(w // 3):
            for i in range(3):
                for j in range(3):
                    color = grid[3 * r + i][3 * c + j]
                    if color not in (0, 5):
                        out[r][c] = color
    return out

